import{_ as p,r as e,o as l,c as i,e as t,a,d as s,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Basic Usage - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Running Raw SQL Queries","slug":"running-raw-sql-queries","link":"#running-raw-sql-queries","children":[{"level":3,"title":"Selecting Records","slug":"selecting-records","link":"#selecting-records","children":[]},{"level":3,"title":"Modifying Records","slug":"modifying-records","link":"#modifying-records","children":[]},{"level":3,"title":"General Statements","slug":"general-statements","link":"#general-statements","children":[]}]},{"level":2,"title":"Multiple Database Connections","slug":"multiple-database-connections","link":"#multiple-database-connections","children":[]},{"level":2,"title":"Database Transactions","slug":"database-transactions","link":"#database-transactions","children":[]},{"level":2,"title":"Database Events","slug":"database-events","link":"#database-events","children":[{"level":3,"title":"Query Logging","slug":"query-logging","link":"#query-logging","children":[]}]}],"relativePath":"3.x/extend/database/basics.md","filePath":"3.x/extend/database/basics.md"}'),u={name:"3.x/extend/database/basics.md"};function d(g,n,k,h,m,b){const o=e("pre-heading"),c=e("post-heading");return l(),i("div",null,[t(o),n[0]||(n[0]=a("h1",null,"Basic Usage",-1)),t(c),n[1]||(n[1]=a("p",null,[s("Connecting to databases and running queries is a simple process, supported by using either raw SQL, the "),a("a",{href:"./query.html"},"query builder"),s(" or "),a("a",{href:"./model.html"},"active record models"),s(". Managing database tables and populating seed data is handled by the "),a("a",{href:"./structure.html"},"migration and seeder process"),s(".")],-1)),n[2]||(n[2]=a("p",null,[s("Raw SQL and using the query builder will perform faster and should be used for simple tasks. Active Record is an approach used by the popular framework, Ruby On Rails. It allows an easy interface for performing repetitive tasks like creating, reading, updating and deleting database records. You can learn more about the "),a("a",{href:"http://en.wikipedia.org/wiki/Active_record_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("active record pattern on Wikipedia"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(".")],-1)),n[3]||(n[3]=r(`<h2 id="running-raw-sql-queries"><a href="#running-raw-sql-queries" class="header-anchor">#</a> Running Raw SQL Queries</h2><p>Once you have configured your database connection, you may run queries using the <code>Db</code> facade. The <code>Db</code> facade provides methods for each type of query: <code>select</code>, <code>update</code>, <code>insert</code>, <code>delete</code>, and <code>statement</code>.</p><h3 id="selecting-records"><a href="#selecting-records" class="header-anchor">#</a> Selecting Records</h3><p>To run a basic query, use the <code>select</code> method on the <code>Db</code> facade.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where active = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first argument passed to the <code>select</code> method is the raw SQL query, while the second argument is any parameter bindings that need to be bound to the query. Typically, these are the values of the <code>where</code> clause constraints. Parameter binding provides protection against SQL injection.</p><p>The <code>select</code> method will always return an <code>array</code> of results. Each result within the array will be a PHP <code>stdClass</code> object, allowing you to access the values of the results:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Instead of using <code>?</code> to represent your parameter bindings, you may execute a query using named bindings.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where id = :id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If database query may produces a singular value, this can be retrieved using the <code>scalar</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">scalar</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select count(*) as count from menu_items&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="modifying-records"><a href="#modifying-records" class="header-anchor">#</a> Modifying Records</h3><p>To execute an <code>insert</code> statement, you may use the <code>insert</code> method on the <code>Db</code> facade. Like <code>select</code>, this method takes the raw SQL query as its first argument and bindings as the second argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;insert into users (id, name) values (?, ?)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>update</code> method should be used to update existing records in the database. The number of rows affected by the statement will be returned by the method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;update users set votes = 100 where name = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>delete</code> method should be used to delete records from the database. Like <code>update</code>, the number of rows deleted will be returned:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deleted</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;delete from users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="general-statements"><a href="#general-statements" class="header-anchor">#</a> General Statements</h3><p>Some database statements should not return any value. For these types of operations, you may use the <code>statement</code> method on the <code>Db</code> facade.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">statement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;drop table users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="multiple-database-connections"><a href="#multiple-database-connections" class="header-anchor">#</a> Multiple Database Connections</h2><p>When <a href="./../../setup/database-config.html">using multiple connections</a>, you may access each connection via the <code>connection</code> method on the <code>Db</code> facade. The <code>name</code> passed to the <code>connection</code> method should correspond to one of the connections listed in your <code>config/database.php</code> configuration file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also access the raw, underlying PDO instance using the <code>getPdo</code> method on a connection instance.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pdo</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getPdo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="database-transactions"><a href="#database-transactions" class="header-anchor">#</a> Database Transactions</h2><p>To run a set of operations within a database transaction, you may use the <code>transaction</code> method on the <code>Db</code> facade. If an exception is thrown within the transaction <code>Closure</code>, the transaction will automatically be rolled back. If the <code>Closure</code> executes successfully, the transaction will automatically be committed. You don&#39;t need to worry about manually rolling back or committing while using the <code>transaction</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">transaction</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you would like to begin a transaction manually and have complete control over rollbacks and commits, you may use the <code>beginTransaction</code> method on the <code>Db</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">beginTransaction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can rollback the transaction via the <code>rollBack</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">rollBack</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Lastly, you can commit a transaction via the <code>commit</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Using the <code>Db</code> facade&#39;s transaction methods also controls transactions for the <a href="./query.html">query builder</a> and <a href="./model.html">model queries</a>.</p></div><h2 id="database-events"><a href="#database-events" class="header-anchor">#</a> Database Events</h2><p>If you would like to receive each SQL query executed by your application, you may use the <code>listen</code> method. This method is useful for logging queries or debugging.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$sql</span><span class="token punctuation">,</span> <span class="token variable">$bindings</span><span class="token punctuation">,</span> <span class="token variable">$time</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may register your query listener in the <code>boot</code> method of a <a href="./../extending.html">plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place this logic.</p><h3 id="query-logging"><a href="#query-logging" class="header-anchor">#</a> Query Logging</h3><p>When query logging is enabled, a log is kept in memory of all queries that have been run for the current request. Call the <code>enableQueryLog</code> method to enable this feature.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">enableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To get an array of the executed queries, you may use the <code>getQueryLog</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$queries</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">getQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>However, in some cases, such as when inserting a large number of rows, this can cause the application to use excess memory. To disable the log, you may use the <code>disableQueryLog</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">disableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>For quicker debugging it may be more useful to call the <code>trace_sql</code> <a href="./../services/log.html">helper function</a> instead.</p></div>`,49))])}const v=p(u,[["render",d]]);export{y as __pageData,v as default};
